const initialState = { value: 0 };

function counterReducer(state = initialState, action) {
  switch (action.type) {
    case 'counter/increment':
      return { value: state.value + 1 };
    case 'counter/decrement':
      return { value: state.value - 1 };
    case 'counter/incrementByAmount':
      return { value: state.value + action.payload };
    default:
      return state;
  }
}

import { createStore } from 'redux';

// 1. Action creators
const increment = () => ({ type: 'counter/increment' });
const decrement = () => ({ type: 'counter/decrement' });

// 2. Reducer
function counter(state = { value: 0 }, action) {
  switch (action.type) {
    case 'counter/increment': return { value: state.value + 1 };
    case 'counter/decrement': return { value: state.value - 1 };
    default: return state;
  }
}

// 3. Store
const store = createStore(counter);

// 4. Subscribe and dispatch
store.subscribe(() => console.log('State:', store.getState()));
store.dispatch(increment()); // State: { value: 1 }
store.dispatch(increment()); // State: { value: 2 }
store.dispatch(decrement()); // State: { value: 1 }
